// ANSIbench LINPACK dgefa/dgesl profile; source and stated modifications are public domain.
const INVALID_RESULT:f64=-1e300;
fn daxpy_r(n:usize,factor:f64,x:&[f64;16],y:&mut[f64;4]){if n==0||factor==0.0{return;}for i in 0..n{y[i]=y[i]+factor*x[i];}}
fn dgefa(a:&mut[f64;16],n:usize,ipvt:&mut[usize;4])->i64{let mut info=0i64;let nm1=n-1;if nm1>=0{for k in 0..nm1{let kp1=k+1;let mut l=k;let mut maximum=a[n*k+k].abs();for i in 1..n-k{let candidate=a[n*k+k+i].abs();if candidate>maximum{l=k+i;maximum=candidate;}}ipvt[k]=l;if a[n*k+l]!=0.0{if l!=k{let t=a[n*k+l];a[n*k+l]=a[n*k+k];a[n*k+k]=t;}let t=-1.0/a[n*k+k];for i in 0..n-(k+1){a[n*k+k+1+i]=t*a[n*k+k+1+i];}for j in kp1..n{let mut t=a[n*j+l];if l!=k{a[n*j+l]=a[n*j+k];a[n*j+k]=t;}let mut x=[0.0;16];let mut y=[0.0;4];for i in 0..n-(k+1){x[i]=a[n*k+k+1+i];y[i]=a[n*j+k+1+i];}daxpy_r(n-(k+1),t,&x,&mut y);for i in 0..n-(k+1){a[n*j+k+1+i]=y[i];}}}else{info=k as i64;}}}ipvt[n-1]=n-1;if a[n*(n-1)+(n-1)]==0.0{info=(n-1)as i64;}info}
fn dgesl(a:&[f64;16],n:usize,ipvt:&[usize;4],b:&mut[f64;4]){let nm1=n-1;if nm1>=1{for k in 0..nm1{let l=ipvt[k];let t=b[l];if l!=k{b[l]=b[k];b[k]=t;}let mut x=[0.0;16];let mut y=[0.0;4];for i in 0..n-(k+1){x[i]=a[n*k+k+1+i];y[i]=b[k+1+i];}daxpy_r(n-(k+1),t,&x,&mut y);for i in 0..n-(k+1){b[k+1+i]=y[i];}}}for kb in 0..n{let k=n-(kb+1);b[k]=b[k]/a[n*k+k];let t=-b[k];let mut x=[0.0;16];let mut y=[0.0;4];for i in 0..k{x[i]=a[n*k+i];y[i]=b[i];}daxpy_r(k,t,&x,&mut y);for i in 0..k{b[i]=y[i];}}}
#[no_mangle]
pub unsafe extern "C" fn linpack_lu_solve(input:*const i64,length:usize)->f64{if input.is_null()||length<1||length>22{return INVALID_RESULT;}let values=unsafe{std::slice::from_raw_parts(input,length)};let raw_n=values[0];if !(2..=4).contains(&raw_n){return INVALID_RESULT;}let n=raw_n as usize;if length!=1+n*n+n{return INVALID_RESULT;}let mut a=[0.0;16];let mut b=[0.0;4];let mut ipvt=[0usize;4];for i in 0..n*n{let value=values[1+i];if !(-8..=8).contains(&value){return INVALID_RESULT;}a[i]=value as f64;}for i in 0..n{let value=values[1+n*n+i];if !(-32..=32).contains(&value){return INVALID_RESULT;}b[i]=value as f64;}if dgefa(&mut a,n,&mut ipvt)!=0{return INVALID_RESULT;}dgesl(&a,n,&ipvt,&mut b);let mut result=0.0;for i in 0..n{result+=(i+1)as f64*b[i];}if result.is_finite(){result}else{INVALID_RESULT}}
